x_comment(x_GiaiTruongSonMountainRange,"A #$MountainRange in #$SouthEastAsia which forms much of the western           border of #$Vietnam with #$Laos and with #$Cambodia.  The range           contains an intricate network of trails, dirt roads and footpaths,           known collectively as the #$HoChiMinhTrail.  The main arteries run           generally north-south along the ridge lines and connect northern           #$Vietnam to southern #$Vietnam, while branches run from the ridge           line east out of the mountains and into the central lowlands of #$Vietnam.           During the #$VietnamWar, the #$HoChiMinhTrail was used extensively           as a major resupply artery for the armed forces of #$NorthVietnam           operating in #$SouthVietnam. (Source: Vietnam -- A Country Study, 1989)") :- x_cid(a65b1280880753).
